import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    target = inputs["target_state"].copy()
    events = inputs["cdc_events"].copy()

    # --- Normalize dtypes defensively ---
    target["order_id"] = target["order_id"].astype("int64")
    target["last_seq"] = target["last_seq"].astype("int64")
    if len(events):
        events["order_id"] = events["order_id"].astype("int64")
        events["seq"] = events["seq"].astype("int64")

    # 1. Duplicate delivery: the same event (same seq) can appear twice ->
    #    apply once.
    events = events.drop_duplicates(subset=["seq"], keep="first")

    # Original per-order watermark (last_seq) from target_state, BEFORE any
    # processing. The replay guard is always evaluated against this static
    # snapshot, not against values updated during this batch.
    orig_last_seq = {
        int(oid): int(ls)
        for oid, ls in zip(target["order_id"], target["last_seq"])
    }

    # 2. Replay guard: drop events for orders that already have a row in
    #    target_state when seq <= that row's last_seq. Orders with no row
    #    in target_state have no guard at all.
    if len(events):
        oid_arr = events["order_id"].to_numpy()
        seq_arr = events["seq"].to_numpy()
        watermark = np.array(
            [orig_last_seq.get(int(o), None) for o in oid_arr], dtype=object
        )
        keep_mask = np.array(
            [
                (wm is None) or (int(s) > int(wm))
                for wm, s in zip(watermark, seq_arr)
            ]
        )
        events = events[keep_mask]

    # 3. Apply remaining events in seq order, per order (cross-order
    #    ordering is irrelevant since orders evolve independently).
    events = events.sort_values(["order_id", "seq"], kind="mergesort")

    # Build mutable state from target_state.
    state = {}
    for _, row in target.iterrows():
        oid = int(row["order_id"])
        state[oid] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": int(row["last_seq"]),
        }

    # Orders that ever had a row (from target_state or created this batch).
    has_had_row = set(state.keys())

    last_event_op = {}
    last_event_seq = {}

    for _, ev in events.iterrows():
        oid = int(ev["order_id"])
        seq = int(ev["seq"])
        op = ev["op"]
        status = ev["status"]
        amount = ev["amount"]

        if op in ("I", "U"):
            if oid in state:
                state[oid]["status"] = status
                if op == "U" and pd.isna(amount):
                    # 'U' with NULL amount leaves existing amount unchanged.
                    pass
                else:
                    state[oid]["amount"] = amount
                state[oid]["last_seq"] = seq
            else:
                # Creation: event amount is taken as-is (NULL stays NULL),
                # regardless of op being 'I' or 'U'.
                state[oid] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq,
                }
            has_had_row.add(oid)
        elif op == "D":
            if oid in state:
                del state[oid]
            # 'D' on a missing order does nothing to the state, but it is
            # still the "last applied event" for tombstone purposes.

        last_event_op[oid] = op
        last_event_seq[oid] = seq

    # --- Build new_state ---
    if state:
        new_state = pd.DataFrame(
            [
                {
                    "order_id": oid,
                    "status": s["status"],
                    "amount": s["amount"],
                    "last_seq": s["last_seq"],
                }
                for oid, s in state.items()
            ]
        )
    else:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    new_state = new_state.reindex(columns=["order_id", "status", "amount", "last_seq"])
    new_state["order_id"] = new_state["order_id"].astype("int64")
    new_state["last_seq"] = new_state["last_seq"].astype("int64")
    new_state["amount"] = new_state["amount"].astype("float64")
    new_state["status"] = new_state["status"].astype(object)

    # --- Build tombstones ---
    tomb_rows = [
        {"order_id": oid, "deleted_seq": last_event_seq[oid]}
        for oid, op in last_event_op.items()
        if op == "D" and oid in has_had_row
    ]

    if tomb_rows:
        tombstones = pd.DataFrame(tomb_rows)
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])

    tombstones = tombstones.reindex(columns=["order_id", "deleted_seq"])
    tombstones["order_id"] = tombstones["order_id"].astype("int64")
    tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")

    return {"new_state": new_state, "tombstones": tombstones}
